begin;
create table if not exists public.municipalities (
  id text primary key,
  country text not null default 'CO' check (country = 'CO'),
  department text not null,
  name text not null,
  unique (department, name)
);
alter table public.municipalities enable row level security;
drop policy if exists "Anyone can read municipalities" on public.municipalities;
create policy "Anyone can read municipalities" on public.municipalities for select to anon, authenticated using (true);
grant select on public.municipalities to anon, authenticated;
revoke insert, update, delete on public.municipalities from anon, authenticated;
