create table if not exists public.communities (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(trim(name)) between 1 and 120)
);
alter table public.communities add column if not exists municipality_id text;
update public.communities set municipality_id = '93' where municipality_id is null;
alter table public.communities alter column municipality_id set not null;
alter table public.communities drop constraint if exists communities_name_key;
do $$ begin
  if not exists (select 1 from pg_constraint where conrelid = 'public.communities'::regclass and conname = 'communities_municipality_id_fkey') then
    alter table public.communities add constraint communities_municipality_id_fkey foreign key (municipality_id) references public.municipalities(id);
  end if;
end $$;
create unique index if not exists communities_city_name_idx on public.communities(municipality_id, lower(trim(name)));
alter table public.communities enable row level security;
drop policy if exists "Anyone can read communities" on public.communities;
create policy "Anyone can read communities" on public.communities
  for select to anon, authenticated using (true);
grant select on public.communities to anon, authenticated;
revoke insert, update, delete on public.communities from anon, authenticated;
-- Comunidad actual confirmada por el propietario: Prato de la Toscana, Sabaneta.
insert into public.communities(id, name, municipality_id)
values ('00000000-0000-4000-8000-000000000001', 'Prato de la Toscana', '93')
on conflict (id) do nothing;
update public.communities set name = 'Prato de la Toscana' where id = '00000000-0000-4000-8000-000000000001' and name = 'Comunidad original';
alter table public.listings add column if not exists community_id uuid;
update public.listings set community_id = '00000000-0000-4000-8000-000000000001' where community_id is null;
alter table public.listings alter column community_id set not null;
-- Compatibilidad durante el despliegue con formularios de la versión anterior.
alter table public.listings alter column community_id set default '00000000-0000-4000-8000-000000000001';
do $$ begin
  if not exists (select 1 from pg_constraint where conrelid = 'public.listings'::regclass and conname = 'listings_community_id_fkey') then
    alter table public.listings add constraint listings_community_id_fkey foreign key (community_id) references public.communities(id);
  end if;
end $$;
alter table public.listings drop constraint if exists listings_building_check;
alter table public.listings add constraint listings_building_check check (char_length(trim(building)) between 1 and 60);
create index if not exists listings_community_date_idx on public.listings(community_id, created_at desc);
commit;
